    #[test]
    fn defaults_uninferred_overload_type_parameters_to_unknown() {
        let parsed = parse_source_file(
            r"
                declare function noArgs(): string;
                declare function proxy<T, U>(fn: (options: T) => U): (options: T) => U;
                declare function proxy<T, U>(fn: (options?: T) => U, noArgs: true): (options?: T) => U;
                const value = proxy(noArgs, true);
            ",
        );
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        let value = bindings.root_scope().unwrap().symbols.get("value").unwrap();
        let type_id = result.type_of_symbol(value).unwrap();

        let Some(TypeKind::Function(signature)) =
            result.types.get(type_id).map(|type_| &type_.kind)
        else {
            panic!("expected function, got {:?}", result.types.get(type_id));
        };
        assert!(signature.parameters_optional);
        let Some(TypeKind::Union(parameters)) = result
            .types
            .get(signature.parameters[0])
            .map(|type_| &type_.kind)
        else {
            panic!("expected optional union");
        };
        assert!(parameters.iter().any(|parameter| {
            matches!(
                result.types.get(*parameter).map(|type_| &type_.kind),
                Some(TypeKind::Unknown)
            )
        }));
    }

    #[test]
    fn preserves_explicit_nested_arrow_type_parameter_returns() {
        let parsed = parse_source_file("const o = <T>(value: T) => (): T => null!;");
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        let o = bindings.root_scope().unwrap().symbols.get("o").unwrap();
        let outer_type = result.type_of_symbol(o).unwrap();
        let TypeKind::Function(outer) = &result.types.get(outer_type).unwrap().kind else {
            panic!("expected outer function");
        };
        let TypeKind::Function(inner) = &result.types.get(outer.return_type).unwrap().kind else {
            panic!("expected inner function");
        };

        assert_eq!(inner.return_type, outer.parameters[0]);
    }

    #[test]
    fn preserves_shadowed_nested_arrow_type_parameters() {
        let parsed = parse_source_file(
            "const foo = <T>(x: T) => { const inner = <T>(y: T) => [x, y] as const; return inner; };",
        );
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        let foo = bindings.root_scope().unwrap().symbols.get("foo").unwrap();
        let outer_type = result.type_of_symbol(foo).unwrap();
        let TypeKind::Function(outer) = &result.types.get(outer_type).unwrap().kind else {
            panic!("expected outer function");
        };
        let TypeKind::Function(inner) = &result.types.get(outer.return_type).unwrap().kind else {
            panic!("expected inner function");
        };
        let TypeKind::ReadonlyTuple(elements) = &result.types.get(inner.return_type).unwrap().kind
        else {
            panic!("expected readonly tuple");
        };

        assert_eq!(result.types.display(elements[0]), "T");
        assert_eq!(result.types.display(elements[1]), "T_1");
        assert!(
            result
                .named_type_references
                .get(&outer.return_type)
                .is_some_and(|reference| reference.name == "__generic_function:T_1=0")
        );
    }

    #[test]
    fn resolves_shadowed_class_names_in_arrow_value_expressions() {
        let parsed = parse_source_file("class A {} const value = <A>(x: A) => new A();");
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        let value = bindings.root_scope().unwrap().symbols.get("value").unwrap();
        let value_type = result.type_of_symbol(value).unwrap();
        let TypeKind::Function(signature) = &result.types.get(value_type).unwrap().kind else {
            panic!("expected function");
        };

        assert!(matches!(
            result
                .types
                .get(signature.return_type)
                .map(|type_| &type_.kind),
            Some(TypeKind::Object(_))
        ));
        assert!(
            result
                .named_type_references
                .get(&signature.return_type)
                .is_some_and(|reference| reference.name == "globalThis.A")
        );
    }

    #[test]
    fn infers_return_type_for_function_namespace_merges() {
        let parsed = parse_source_file(
            "function ExpandoMerge(n: number) { return n; } namespace ExpandoMerge { export interface I {} }",
        );
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        let function = parsed
            .arena
            .iter()
            .find_map(|(id, node)| {
                matches!(node.data, NodeData::FunctionDeclaration(_)).then_some(id)
            })
            .unwrap();
        let type_id = result.type_of_node(function).unwrap();
        let signature =
            match result.types.get(type_id).map(|type_| &type_.kind) {
                Some(TypeKind::Function(signature)) => Some(signature),
                Some(TypeKind::Intersection(members)) => members.iter().find_map(|member| {
                    match result.types.get(*member).map(|type_| &type_.kind) {
                        Some(TypeKind::Function(signature)) => Some(signature),
                        _ => None,
                    }
                }),
                _ => None,
            }
            .unwrap_or_else(|| {
                panic!(
                    "expected callable merge, got {:?}",
                    result.types.get(type_id)
                )
            });

        assert_eq!(signature.return_type, result.types.number());
    }

    #[test]
    fn drops_named_provenance_with_unresolved_inferred_type_arguments() {
        let parsed = parse_source_file(
            r#"
                type OptionalOnly<K extends "only" = "only"> = { [P in K]: {
                    value?: undefined;
                } }[K];
                declare function optionalOnly<K extends "only">(value: OptionalOnly<K>): OptionalOnly<K>;
                const result = optionalOnly<"only">({});
            "#,
        );
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        let value = bindings
            .root_scope()
            .unwrap()
            .symbols
            .get("result")
            .unwrap();
        let type_id = result.type_of_symbol(value).unwrap();

        assert!(
            !result.named_type_references.contains_key(&type_id),
            "unexpected provenance: {:?}",
            result.named_type_references.get(&type_id)
        );
        assert!(
            matches!(
                result.types.get(type_id).map(|type_| &type_.kind),
                Some(TypeKind::Object(_))
            ),
            "{}",
            result.types.display(type_id)
        );
    }

    #[test]
    fn const_assertions_preserve_readonly_tuple_objects_and_literals() {
        let parsed =
            parse_source_file(r#"const ALL_BARS = [{ name: "a" }, { name: "b" }] as const;"#);
        assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        let symbol = bindings
            .root_scope()
            .unwrap()
            .symbols
            .get("ALL_BARS")
            .unwrap();
        let type_id = result.type_of_symbol(symbol).unwrap();
        let TypeKind::ReadonlyTuple(elements) = &result.types.get(type_id).unwrap().kind else {
            panic!(
                "expected readonly tuple, got {}",
                result.types.display(type_id)
            );
        };
        assert_eq!(elements.len(), 2);
        for (element, expected) in elements.iter().zip(["a", "b"]) {
            let TypeKind::Object(object) = &result.types.get(*element).unwrap().kind else {
                panic!("expected object element");
            };
            assert!(object.readonly_properties.contains("name"));
            assert!(matches!(
                result.types.get(object.properties["name"]).map(|type_| &type_.kind),
                Some(TypeKind::StringLiteral(value)) if value == expected
            ));
        }
    }

