    #[test]
    fn narrows_truthiness_discriminants_in_and_instanceof() {
        let parsed = parse_source_file(
            r#"
                type Shape =
                    { kind: "circle"; radius: number } |
                    { kind: "square"; side: number };
                function area(shape: Shape): number {
                    if (shape.kind === "circle") { return shape.radius; }
                    return shape.side;
                }

                type TextOrCount = { text: string } | { count: number };
                function inspect(value: TextOrCount): void {
                    if ("text" in value) {
                        const text: string = value.text;
                    } else {
                        const count: number = value.count;
                    }
                }

                class Dog { bark: string; }
                class Cat { meow: string; }
                function pet(value: Dog | Cat): void {
                    if (value instanceof Dog) {
                        value.bark;
                        value.meow;
                    } else {
                        value.meow;
                    }
                }

                function truthy(value: string | null): void {
                    if (value) {
                        const text: string = value;
                    } else {
                        const bad: number = value;
                    }
                }
            "#,
        );
        assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        assert_eq!(
            result
                .diagnostics
                .iter()
                .map(|diagnostic| diagnostic.diagnostic.code())
                .collect::<Vec<_>>(),
            [2339, 2322],
            "{:?}",
            result
                .diagnostics
                .iter()
                .map(|diagnostic| diagnostic.diagnostic.render().unwrap())
                .collect::<Vec<_>>()
        );
    }

    #[test]
    fn infers_logical_or_from_truthy_left_constituents() {
        let parsed = parse_source_file(
            r#"
                const callable = (() => 1) || "unreachable";
                const object = {} || "unreachable";
                const falseResult = false || "fallback";
                const zeroResult = 0 || "fallback";
                const emptyResult = "" || 1;
                let maybe: (() => number) | null;
                const mixed = maybe || "fallback";
                let booleanValue: boolean;
                const booleanResult: true | string = booleanValue || "fallback";
            "#,
        );
        assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        assert!(result.diagnostics.is_empty(), "{:?}", result.diagnostics);
        let root = bindings.root_scope().unwrap();
        let kind = |name: &str| {
            let symbol = root.symbols.get(name).unwrap();
            &result
                .types
                .get(result.type_of_symbol(symbol).unwrap())
                .unwrap()
                .kind
        };

        assert!(matches!(kind("callable"), TypeKind::Function(_)));
        assert!(matches!(kind("object"), TypeKind::Object(_)));
        assert!(
            matches!(kind("falseResult"), TypeKind::StringLiteral(value) if value == "fallback")
        );
        assert!(
            matches!(kind("zeroResult"), TypeKind::StringLiteral(value) if value == "fallback")
        );
        assert!(matches!(kind("emptyResult"), TypeKind::NumberLiteral(value) if value == "1"));
        let TypeKind::Union(mixed) = kind("mixed") else {
            panic!("expected truthy function and fallback union");
        };
        assert_eq!(mixed.len(), 2);
        assert!(mixed.iter().any(|member| matches!(
            result.types.get(*member).map(|type_| &type_.kind),
            Some(TypeKind::Function(_))
        )));
    }

    #[test]
    fn joins_assignments_and_checks_switch_returns_and_unreachable_code() {
        let parsed = parse_source_file(
            r#"
                function assign(flag: boolean): void {
                    let value: string | number = "start";
                    value = 1;
                    const numberValue: number = value;
                    if (flag) { value = "next"; } else { value = 2; }
                    const joined: string | number = value;
                    const bad: boolean = value;
                    while (flag) { value = 3; }
                    const loopJoined: string | number = value;
                }

                type Token = { kind: "a"; a: number } | { kind: "b"; b: string };
                function exhaustive(token: Token): string | number {
                    switch (token.kind) {
                        case "a": return token.a;
                        case "b": return token.b;
                    }
                }
                function incomplete(token: Token): string | number {
                    switch (token.kind) {
                        case "a": return token.a;
                    }
                }
                function unreachable(): number {
                    return 1;
                    const after = 2;
                }
                function thrown(): number { throw "done"; }
            "#,
        );
        assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file(&parsed.arena, parsed.source_file, &bindings);
        assert_eq!(
            result
                .diagnostics
                .iter()
                .map(|diagnostic| diagnostic.diagnostic.code())
                .collect::<Vec<_>>(),
            [2322, 2355]
        );
    }

    #[test]
    fn enforces_control_flow_compiler_options() {
        let parsed = parse_source_file(
            r"
                function choose(value: boolean) { if (value) return 1; }
                function cases(value: number) {
                    switch (value) { case 1: value++; case 2: break; }
                }
                function unreachable() { return; const after = 1; }
                try { throw 1; } catch (error) { error.toFixed(); }
            ",
        );
        assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let result = check_source_file_with_options(
            &parsed.arena,
            parsed.source_file,
            &bindings,
            CheckerOptions {
                allow_unreachable_code: Some(false),
                no_fallthrough_cases_in_switch: true,
                no_implicit_returns: true,
                use_unknown_in_catch_variables: true,
                ..CheckerOptions::default()
            },
        );
        assert_eq!(
            result
                .diagnostics
                .iter()
                .map(|diagnostic| diagnostic.diagnostic.code())
                .collect::<Vec<_>>(),
            [7030, 7029, 7027, 18046]
        );
        assert_eq!(
            result
                .diagnostics
                .iter()
                .map(|diagnostic| diagnostic.diagnostic.render().unwrap())
                .collect::<Vec<_>>(),
            [
                "Not all code paths return a value.",
                "Fallthrough case in switch.",
                "Unreachable code detected.",
                "'error' is of type 'unknown'.",
            ]
        );
    }

