    #[test]
    fn leaves_internal_import_equals_aliases_on_runtime_fallback() {
        let parsed = parse_source_file(
            r#"
                import alias = require("foo");
                import { alias as alias2 } from "bar";
                import cls = alias.Class;
                export import cls2 = alias.Class;
                import cls3 = alias2.Class;
                let x = new cls();
                let y = new cls2();
                let z = new cls3();
                namespace M {
                    export import cls = alias.Class;
                    let value = new cls();
                }
            "#,
        );
        assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        let modules = BTreeMap::new();
        let checked = check_program(&[ProgramSource {
            arena: &parsed.arena,
            source_file: parsed.source_file,
            bindings: &bindings,
            resolved_modules: &modules,
            is_default_library: false,
            skip_diagnostics: false,
            checker_options: CheckerOptions::default(),
        }]);
        let meanings = &checked.files[0].import_runtime_meanings;
        assert!(meanings.is_empty(), "{meanings:?}");
        for (node, data) in parsed.arena.iter() {
            let NodeData::ImportEqualsDeclaration(import) = &data.data else {
                continue;
            };
            if !matches!(
                parsed
                    .arena
                    .get(import.module_reference)
                    .map(|node| &node.data),
                Some(NodeData::ExternalModuleReference(_))
            ) {
                assert!(!meanings.contains_key(&node));
            }
        }
    }

    #[test]
    fn instantiates_imported_remapped_types_without_implicit_undefined() {
        let dependency = parse_source_file(
            r#"
                type Id<T> = { [K in keyof T]: T[K] } & {};
                export declare function createApi<Definitions>(value: { endpoints: Definitions }): {
                    [K in keyof Definitions as `use${Capitalize<K & string>}Query`]: () => Id<{
                        status: "uninitialized";
                        originalArgs?: never;
                    }>;
                };
            "#,
        );
        let consumer = parse_source_file(
            r#"
                import { createApi } from "./createApi";
                const slice = createApi({ endpoints: { test: { url: "/user" } } });
            "#,
        );
        let dependency_bindings = bind_source_file(&dependency.arena, dependency.source_file);
        let consumer_bindings = bind_source_file(&consumer.arena, consumer.source_file);
        let no_modules = BTreeMap::new();
        let consumer_modules = BTreeMap::from([("./createApi".into(), 0)]);
        let loose = CheckerOptions {
            strict_null_checks: false,
            ..CheckerOptions::default()
        };
        let checked = check_program(&[
            ProgramSource {
                arena: &dependency.arena,
                source_file: dependency.source_file,
                bindings: &dependency_bindings,
                resolved_modules: &no_modules,
                is_default_library: false,
                skip_diagnostics: false,
                checker_options: loose,
            },
            ProgramSource {
                arena: &consumer.arena,
                source_file: consumer.source_file,
                bindings: &consumer_bindings,
                resolved_modules: &consumer_modules,
                is_default_library: false,
                skip_diagnostics: false,
                checker_options: loose,
            },
        ]);
        let slice = consumer_bindings
            .root_scope()
            .unwrap()
            .symbols
            .get("slice")
            .unwrap();
        let slice_type = checked.files[1].type_of_symbol(slice).unwrap();
        let TypeKind::Object(slice) = &checked.files[1].types.get(slice_type).unwrap().kind else {
            panic!("expected mapped object");
        };
        let query_type = slice.properties["useTestQuery"];
        let TypeKind::Function(query) = &checked.files[1].types.get(query_type).unwrap().kind
        else {
            panic!("expected query function");
        };
        let result = match &checked.files[1].types.get(query.return_type).unwrap().kind {
            TypeKind::Object(object) => object,
            TypeKind::Intersection(return_types) => return_types
                .iter()
                .find_map(|member| match &checked.files[1].types.get(*member)?.kind {
                    TypeKind::Object(object) if object.properties.contains_key("originalArgs") => {
                        Some(object)
                    }
                    _ => None,
                })
                .unwrap(),
            kind => panic!("expected identity object, got {kind:?}"),
        };
        assert!(result.optional_properties.contains("originalArgs"));
        assert!(matches!(
            checked.files[1]
                .types
                .get(result.properties["originalArgs"])
                .map(|type_| &type_.kind),
            Some(TypeKind::Never)
        ));
    }

    #[test]
    fn applies_explicit_type_arguments_to_imported_generic_calls() {
        let provider = parse_source_file("export declare function create<T>(): () => T;");
        let consumer = parse_source_file(
            r#"
                import { create } from "./provider";
                type A = { a: string };
                type B = { b: number };
                export const one = create<A>();
                export const two = create<B>();
            "#,
        );
        let provider_bindings = bind_source_file(&provider.arena, provider.source_file);
        let consumer_bindings = bind_source_file(&consumer.arena, consumer.source_file);
        let no_modules = BTreeMap::new();
        let consumer_modules = BTreeMap::from([("./provider".into(), 0)]);
        let checked = check_program(&[
            ProgramSource {
                arena: &provider.arena,
                source_file: provider.source_file,
                bindings: &provider_bindings,
                resolved_modules: &no_modules,
                is_default_library: false,
                skip_diagnostics: false,
                checker_options: CheckerOptions::default(),
            },
            ProgramSource {
                arena: &consumer.arena,
                source_file: consumer.source_file,
                bindings: &consumer_bindings,
                resolved_modules: &consumer_modules,
                is_default_library: false,
                skip_diagnostics: false,
                checker_options: CheckerOptions::default(),
            },
        ]);
        for (symbol_name, alias_name) in [("one", "A"), ("two", "B")] {
            let symbol = consumer_bindings
                .root_scope()
                .unwrap()
                .symbols
                .get(symbol_name)
                .unwrap();
            let outer = checked.files[1].type_of_symbol(symbol).unwrap();
            let TypeKind::Function(outer) = &checked.files[1].types.get(outer).unwrap().kind else {
                panic!("expected imported call result");
            };
            let reference = checked.files[1]
                .named_type_references
                .get(&outer.return_type)
                .unwrap();
            assert_eq!(reference.name, alias_name);
        }
    }

    #[test]
    fn checks_namespace_member_with_container_name_without_recursive_symbol() {
        let parsed =
            parse_source_file("namespace m1 { export var m1 = 10; var b = m1; } var foo = m1.m1;");
        assert!(parsed.diagnostics.is_empty(), "{:?}", parsed.diagnostics);
        let bindings = bind_source_file(&parsed.arena, parsed.source_file);
        assert!(
            bindings.diagnostics.is_empty(),
            "{:?}",
            bindings.diagnostics
        );
        let modules = BTreeMap::new();
        let checked = check_program(&[ProgramSource {
            arena: &parsed.arena,
            source_file: parsed.source_file,
            bindings: &bindings,
            resolved_modules: &modules,
            is_default_library: false,
            skip_diagnostics: false,
            checker_options: CheckerOptions::default(),
        }]);
        assert!(checked.files[0].diagnostics.is_empty());

        let namespace = bindings.root_scope().unwrap().symbols.get("m1").unwrap();
        let member = bindings
            .symbols
            .get(namespace)
            .unwrap()
            .members
            .get("m1")
            .unwrap();
        assert_ne!(namespace, member);
        let member_type = checked.files[0].type_of_symbol(member).unwrap();
        assert!(matches!(
            checked.files[0].types.get(member_type).unwrap().kind,
            TypeKind::Number | TypeKind::NumberLiteral(_)
        ));
    }

    #[test]
